theorem IsSide.notMem_support [DecidableEq V] {S : Set V} {x y : V} (hS : IsSide G S x y) {a b : V}
    {p : G.Walk a b} (hp : p.IsPath) (ha : a ∉ S) (hb : b ∉ S) {u : V} (hu : u ∈ p.support) :
    u ∉ S

theorem isSide_leaf' {b b' : ValidBlock m} {i : Fin (m + 1)} {x : Slot}
    (hb : b.val = Block.leaf i x) (hb' : b'.val = Block.spine i) :
    IsSide (G' m) {z | blockOf z = some b} (Vtx.mk b x) (Vtx.mk b' x)

theorem isSide_spine' {b b' : ValidBlock m} {i j : Fin (m + 1)}
    (hb : b.val = Block.spine i) (hb' : b'.val = Block.spine j) (hij : (i : ℕ) + 1 = (j : ℕ)) :
    IsSide (G' m) {z | ∃ bb : ValidBlock m, blockOf z = some bb ∧ (bb.val.idx : ℕ) ≤ (i : ℕ)}
      (Vtx.mk b Slot.c) (Vtx.mk b' Slot.a)

theorem cycle_two_nbrs {V : Type*} [DecidableEq V] {Gr : SimpleGraph V} (c : Cycle Gr) {u : V}
    (hu : u ∈ c.walk.support) :
    ∃ y z : V, y ≠ z ∧ ∀ x, s(u, x) ∈ c.edges ↔ (x = y ∨ x = z)

theorem exists_subwalk {p q : Vtx m} (P : (G' m).Walk p q) {u₁ u₂ : Vtx m}
    (h₁ : u₁ ∈ P.support) (h₂ : u₂ ∈ P.support) :
    ∃ W : (G' m).Walk u₁ u₂, ∀ e ∈ W.edges, e ∈ P.edges

theorem sameBlock_of_chord {p q : Vtx m} (P : (G' m).Walk p q) {u₁ u₂ : Vtx m}
    (hadj : (G' m).Adj u₁ u₂) (h₁ : u₁ ∈ P.support) (h₂ : u₂ ∈ P.support)
    (hnot : s(u₁, u₂) ∉ P.edges) : blockOf u₁ = blockOf u₂

theorem deficient_subset (b : ValidBlock m) :
    (visitedSlots c b).filter (fun s => ¬ (s ∈ usedRim c b ∧ s.pred ∈ usedRim c b)) ⊆
      {exitSlot b p, exitSlot b q}

theorem rimAdj_exitSlots_of_chord {b : ValidBlock m}
    (hne : (rimSpanS (visitedSlots c b) \ usedRim c b).Nonempty) :
    Slot.rimAdjB (exitSlot b p) (exitSlot b q) = true

private theorem sum_slot_leaf (m : ℕ) (i : Fin (m + 1)) :
    (∑ x : Slot, if (Block.leaf i x).validB = true then 1 else 0)
      = 3 + ((if (i : ℕ) = 0 then 1 else 0) + (if (i : ℕ) = m then 1 else 0))

theorem G'_adj_of_inter {b₁ b₂ : ValidBlock m} {s₁ s₂ : Slot}
    (h : interAdjVB (Vtx.mk b₁ s₁) (Vtx.mk b₂ s₂) = true) :
    (G' m).Adj (Vtx.mk b₁ s₁) (Vtx.mk b₂ s₂)

lemma slots_of_interAdjVB {b b' : ValidBlock m} {s s' : Slot}
    (h : interAdjVB (Vtx.mk b s) (Vtx.mk b' s') = true) :
    s = Block.attachSlot b.val b'.val ∧ s' = Block.attachSlot b'.val b.val

lemma spine_of_G'_adj_leaf {b b' : ValidBlock m} {s s' : Slot} {i : Fin (m + 1)} {x : Slot}
    (hb : b.val = Block.leaf i x) (hne : b ≠ b')
    (h : (G' m).Adj (Vtx.mk b s) (Vtx.mk b' s')) : b'.val = Block.spine i

private theorem greedy [DecidableEq V] (h : IsTwoDegenerate H) :
    ∀ n : ℕ, ∀ s : Finset V, s.card ≤ n →
      ∃ C : V → Fin 3, ∀ u ∈ s, ∀ v ∈ s, H.Adj u v → C u ≠ C v

private theorem spine_a_ne_alpha_aux :
    ∀ (n : ℕ) (i : Fin (m + 1)), (i : ℕ) = n →
      C (Vtx.mk (spineVB i) Slot.a) ≠ alphaColor C

theorem isTwoDegenerate_of_forall_set {V : Type*} {H : SimpleGraph V}
    (h : ∀ s : Set V, s.Nonempty → ∃ u ∈ s, {z | z ∈ s ∧ H.Adj u z}.encard ≤ 2) :
    IsTwoDegenerate H

theorem encard_le_two_of_subset_neighborSet_diff (m : ℕ) (hm : 1 ≤ m) {p w : Vtx m}
    (hp : p ≠ Vtx.v m) (hw : (G m).Adj p w) {T : Set (Vtx m)}
    (hT : T ⊆ ((G m).neighborSet p : Set (Vtx m)) \ {w}) : T.encard ≤ 2

theorem subgraph_chromaticNumber_map_equiv {V W : Type*} (e : V ≃ W) (H : SimpleGraph V) {n : ℕ}
    (h : ∀ K : H.Subgraph, K ≠ ⊤ → K.coe.chromaticNumber ≤ n) :
    ∀ K : (H.map e.toEmbedding).Subgraph, K ≠ ⊤ → K.coe.chromaticNumber ≤ n

theorem cycle_chords_congr {V W : Type*} {H : SimpleGraph V} {H' : SimpleGraph W}
    (φ : H ≃g H') {k : ℕ}
    (h : ∀ c : Cycle H, c.chords.encard ≤ k) :
    ∀ c : Cycle H', c.chords.encard ≤ k

theorem cycle_chords_map_equiv {V W : Type*} (e : V ≃ W) (H : SimpleGraph V) {k : ℕ}
    (h : ∀ c : Cycle H, c.chords.encard ≤ k) :
    ∀ c : Cycle (H.map e.toEmbedding), c.chords.encard ≤ k
